import { describe, it, expect } from 'vitest'
import { getTotalStats, attackStatKey, makeDefaultWallet } from '../src/engine/stats'
import { classes, races } from '../src/data'

// Parity fixtures generated by RUNNING the bot's own lib/game-data.js
// getTotalStats() against the same inputs.

describe('getTotalStats (bot parity)', () => {
  it('warrior/human/level 1', () => {
    expect(getTotalStats('warrior', 'human', 1)).toEqual({
      str: 10, agi: 5, int: 2, def: 8, lck: 3, maxHp: 150, maxMp: 30,
    })
  })

  it('mage/elf/level 10', () => {
    expect(getTotalStats('mage', 'elf', 10)).toEqual({
      str: 2, agi: 8, int: 32, def: 1, lck: 5, maxHp: 170, maxMp: 195,
    })
  })

  it('assassin/orc/level 50', () => {
    expect(getTotalStats('assassin', 'orc', 50)).toEqual({
      str: 9, agi: 110, int: 3, def: 4, lck: 8, maxHp: 580, maxMp: 315,
    })
  })

  it('cleric/fairy/level 100', () => {
    expect(getTotalStats('cleric', 'fairy', 100)).toEqual({
      str: 2, agi: 8, int: 213, def: 6, lck: 7, maxHp: 1100, maxMp: 615,
    })
  })

  it('throws on unknown class/race', () => {
    expect(() => getTotalStats('necromancer', 'human', 1)).toThrow('Unknown classId')
    expect(() => getTotalStats('warrior', 'dragon', 1)).toThrow('Unknown raceId')
  })

  it('level below 1 clamps growth at level 1', () => {
    expect(getTotalStats('warrior', 'human', 0)).toEqual(getTotalStats('warrior', 'human', 1))
  })
})

describe('primary stat by class', () => {
  it('maps classes to their design primary stat', () => {
    expect(attackStatKey({ classId: 'warrior' })).toBe('str')
    expect(attackStatKey({ classId: 'samurai' })).toBe('str')
    expect(attackStatKey({ classId: 'rogue' })).toBe('agi')
    expect(attackStatKey({ classId: 'assassin' })).toBe('agi')
    expect(attackStatKey({ classId: 'mage' })).toBe('int')
    expect(attackStatKey({ classId: 'cleric' })).toBe('int')
  })

  it('defaults to str for unknown classes', () => {
    expect(attackStatKey({ classId: '???' })).toBe('str')
  })
})

describe('starting wallet', () => {
  it('solars start at 100, the rest at 0 (data/currency.json)', () => {
    const w = makeDefaultWallet()
    expect(w.solars).toBe(100)
    expect(w.gems).toBe(0)
  })
})

describe('data sanity', () => {
  it('ships the 9 classes and 5 starting races (fairy is hidden/transformation-only)', () => {
    expect(Object.keys(classes)).toHaveLength(9)
    expect(Object.keys(races)).toHaveLength(6)
    const visible = Object.keys(races).filter((r) => races[r].hidden !== true)
    expect(visible).toHaveLength(5)
    expect(visible).toEqual(['human', 'elf', 'dwarf', 'orc', 'halfling'])
    expect(races.fairy!.hidden).toBe(true)
  })
})
